#include <limits.h>
#include <stdio.h>
int main(void) {
    volatile unsigned int top = UINT_MAX;
    unsigned int result = top + 1u;
    printf("%u\n", result);
    return 0;
}

#include <stdio.h>
int main(void) {
    fputs("月光把旧信折成一只船，\n让沉默沿着窗台远航。\n", stdout);
    return 0;
}

#include <math.h>
#include <stdio.h>
int main(void) {
    volatile double square = 9.0;
    volatile double angle = 0.0;
    printf("%.0f %.0f\n", sqrt(square), cos(angle));
    return 0;
}

#include <stddef.h>
#include <stdio.h>
int main(void) {
    int values[3] = {4, 5, 6};
    int *end = values + 3;
    ptrdiff_t length = end - values;
    printf("%td %d\n", length, *(end - 1));
    return 0;
}

#include <limits.h>
#include <stdio.h>
int main(void) {
    volatile int near_top = INT_MAX - 1;
    int result = near_top + 1;
    printf("%d\n", result == INT_MAX);
    return 0;
}

#include <stdio.h>
int main(void) {
    volatile unsigned int value = 1u;
    volatile int shift = 3;
    printf("%u\n", value << shift);
    return 0;
}

#include <stdio.h>
int main(void) {
    int values[3] = {4, 5, 6};
    volatile int index = 3;
    printf("%d\n", values[index]);
    return 0;
}

#include <limits.h>
#include <stdio.h>
int main(void) {
    volatile int top = INT_MAX;
    printf("%d\n", top + 1);
    return 0;
}

#include <stdio.h>
int main(void) {
    volatile int numerator = 7;
    volatile int denominator = 0;
    printf("%d\n", numerator / denominator);
    return 0;
}

#include <limits.h>
#include <stdio.h>
int main(void) {
    volatile unsigned int value = 1u;
    volatile unsigned int shift = sizeof(unsigned int) * CHAR_BIT;
    printf("%u\n", value << shift);
    return 0;
}

#include <stdio.h>
int main(void) {
    volatile int value = -1;
    volatile int shift = 1;
    printf("%d\n", value << shift);
    return 0;
}

#include <stddef.h>
#include <stdio.h>
int main(void) {
    int value = 7;
    int *pointer = &value;
    volatile int choose_null = 1;
    if (choose_null) {
        pointer = NULL;
    }
    printf("%d\n", *pointer);
    return 0;
}

#include <stdio.h>
int main(void) {
    int values[2] = {8, 9};
    volatile int take_bad_branch = 0;
    if (take_bad_branch) {
        volatile int index = 2;
        printf("%d\n", values[index]);
    } else {
        puts("safe branch");
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
int main(void) {
    volatile int *values = malloc(2 * sizeof *values);
    if (values == NULL) {
        return 2;
    }
    values[0] = 4;
    values[1] = 5;
    volatile int index = 2;
    values[index] = 6;
    printf("%d\n", values[index]);
    free((void *)values);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
int main(void) {
    int *value = malloc(sizeof *value);
    if (value == NULL) {
        return 2;
    }
    *value = 7;
    free(value);
    printf("%d\n", *(volatile int *)value);
    return 0;
}
